import java.io.*;
import java.util.*;

public class Main {
    static int[] dsu;

    static int find(int x) {
        int r = x;
        while (dsu[r] != r) r = dsu[r];
        while (dsu[x] != r) {
            int nx = dsu[x];
            dsu[x] = r;
            x = nx;
        }
        return r;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); int N = (int) st.nval;
        st.nextToken(); int B = (int) st.nval;

        int[] ei = new int[B], ej = new int[B], ep = new int[B];
        Integer[] ord = new Integer[B];
        for (int i = 0; i < B; i++) {
            st.nextToken(); ei[i] = (int) st.nval;
            st.nextToken(); ej[i] = (int) st.nval;
            st.nextToken(); ep[i] = (int) st.nval;
            ord[i] = i;
        }
        Arrays.sort(ord, (a, b) -> Integer.compare(ep[b], ep[a]));

        int M = N + B + 2;
        int[] par = new int[M];
        int[] wt = new int[M];
        int[] dep = new int[M];
        dsu = new int[M];
        for (int i = 1; i <= N; i++) dsu[i] = i;

        int cnt = N + 1;
        for (int k = 0; k < B; k++) {
            int e = ord[k];
            int a = find(ei[e]);
            int b = find(ej[e]);
            if (a == b) continue;
            int v = cnt++;
            par[a] = v;
            par[b] = v;
            wt[v] = ep[e];
            dsu[a] = v;
            dsu[b] = v;
        }

        int R = cnt;
        for (int t = 1; t < cnt; t++) {
            if (dsu[t] == t) par[t] = R;
        }
        par[R] = R;

        // depth: every parent has a larger index than its child (creation order)
        for (int t = cnt - 1; t >= 1; t--) {
            dep[t] = dep[par[t]] + 1;
        }

        int LOG = 1;
        while ((1 << LOG) < M) LOG++;

        int[][] up = new int[LOG][M];
        for (int t = 1; t <= R; t++) up[0][t] = par[t];
        for (int k = 1; k < LOG; k++) {
            int[] upk = up[k];
            int[] upk1 = up[k - 1];
            for (int t = 1; t <= R; t++) upk[t] = upk1[upk1[t]];
        }

        st.nextToken(); int C = (int) st.nval;
        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < C; q++) {
            st.nextToken(); int x = (int) st.nval;
            st.nextToken(); int y = (int) st.nval;

            int a = x, b = y;
            if (dep[a] < dep[b]) { int t = a; a = b; b = t; }
            int d = dep[a] - dep[b];
            for (int k = 0; k < LOG; k++) {
                if ((d & (1 << k)) != 0) a = up[k][a];
            }
            if (a == b) {
                sb.append(wt[a]).append('\n');
            } else {
                for (int k = LOG - 1; k >= 0; k--) {
                    if (up[k][a] != up[k][b]) {
                        a = up[k][a];
                        b = up[k][b];
                    }
                }
                sb.append(wt[up[0][a]]).append('\n');
            }
        }
        System.out.print(sb);
    }
}
